import csv,json,re,collections
from pathlib import Path
rows=[r for r in csv.DictReader(open('D1/in/part-mint.tsv'),delimiter='\t') if r['kind']=='L1:package:dpkg-query'][:635]
out={r['id']:r for r in csv.DictReader(open('D1/c1/part-mint.1.tsv'),delimiter='\t')};s=json.load(open('D1/c1/part-mint.1.sources.json'));fl=json.load(open('D1/c1/part-mint.1.filelists.json'))
lines=['# Package classification notes, assigned first segment','', 'Scope: first 635 dpkg-query rows. No earlier classification was consulted. Installed identities and versions were established from the supplied inventory. Public archive metadata establishes package function; archive descriptions are not inventory classifications. No objects were removed and no machine experiments were run.','', 'Each inventory row here is one package, not a directory group of independently enumerated members. A package containing runnable code is classified by the contribution of that code; accompanying manuals do not turn the entire package into exempt content. Dependency-only packages were examined separately.','', '## Sentences used','']
ids={'S2.2-1','S2.2-2','S2.2-4','S2.2-6','S2.2-7','S2.2-9','S2.2-10','S2.2-13','S2.2-16','S3-1','S3-2'}
for line in Path('SENTENCES.md').read_text().splitlines():
 if any(line.startswith('- **'+i+'** ') for i in ids):lines.append(line)
lines+=['','## Homogeneous rules and manual checks','','No name prefix alone determines executable status. The explicitly selected ordinary-program and runtime-library sets were read against their package descriptions. Data, configuration, firmware, compiler dependency packages, debugging packages and common-file packages received separate examination.','', 'R1: A package supplying an independently runnable program is MUST under S2.2-9. The following ten entries were checked manually: each description identifies the executable and its task.','']
samples=[('R1',[0,1,2,3,4,9,11,12,14,16]),('R2',[433,434,435,436,437,438,439,441,442,443]),('R3',[229,230,231,232,233,234,235,236,237,238]),('R4',list(range(186,196))),('R5',[5,13,19,21,41,71,75,80,141,147])]
texts={'R2':'R2: A documented executable library or native runtime module is MUST under S2.2-10 and S2.2-13: the caller executes its code with the caller’s rights. This rule excludes detached symbols, development data and common-file packages. Ten manually checked entries follow.', 'R3':'R3: Runtime introspection metadata is MUST under S2.2-1 and S2.2-2 because it enables language bindings to call the native API. It is not displayed document content. Official project documentation at https://gi.readthedocs.io/en/latest/ states: “Then language bindings can read this metadata and automatically provide bindings to call into the C library.” Ten manually checked package descriptions identify introspection or typelib data.', 'R4':'R4: Font packages are HOLE under S2.2-2 and S2.2-4: removing glyphs and metrics can mean only losing graphical content, or losing the ability to render particular characters correctly. The text supplies no boundary between these readings. Ten manually checked packages supply glyphs and metrics, not font-management executables.', 'R5':'R5: Pure text, image and descriptive-content packages are NOT under S2.2-4: removal loses the supplied content while leaving executable capabilities. This rule is not applied automatically to every data/common suffix. Ten manually checked entries below identify such content; system-routing configuration, processing schemas, code hidden in data packages and other exceptions were examined separately.'}
for label,indices in samples:
 if label!='R1':lines+=['',texts[label],'']
 for i in indices:
  r=rows[i];n=r['name'].split(':')[1];lines.append(f'- `{r["id"]}` (`{n}`): “{s[n]["description"]}”; checked against {out[r["id"]]["decision"]} rationale.')
lines+=['','## Individually assessed exceptions','','The explicit per-index assignments in part-mint.1.finish.py record individual assessments, not a suffix-derived blanket rule. Their row reasons state the relevant removal consequence or missing boundary. The following distinctions were checked:', '', '- Firmware packages change device behavior; system-update availability establishes the condition in S2.2-16.', '- Shared hardware routing, keyboard configuration, desktop schemas and interprocess messaging extend across programs and therefore do not fit the one-program setting exemption.', '- Dependency-only metapackages expose an unspecified removal boundary: remove just the dependency record, or the functionality selected through it. No external package-manager removal semantics were silently substituted for the text.', '- Detached debugging symbols expose content versus symbolic-debugging-capability readings. The separate unstripped-binary debugging package explicitly supplies executable code and was classified MUST.', '- Dictionaries, processing schemas, templates, color profiles and keyboard maps received individual HOLE explanations; knowing their role does not resolve the text’s content/capability boundary.', '- Shared-library configuration exposes a separate one-program versus multiple-caller ambiguity.', '- Data/common names are insufficient: the primary file lists establish executable modules in cinnamon-common and hplip-data, service activation in evolution-data-server-common, and only documentation in gcc base packages.', '- No UNKNOWN was needed after consulting the public metadata and file lists.', '', '## Package-specific documentary evidence', '', 'The following quotations are package description titles, keyed to exact inventory ids. Additional full descriptions and file lists were consulted for ambiguous titles; selected file paths follow below. The descriptions establish roles, not normative decisions. Current archive descriptions are used for stable package purpose; an installed version need not equal the archive revision. Mint-origin descriptions replace conflicting distribution descriptions, notably the browser package.', '']
for r in rows:
 n=r['name'].split(':')[1];d=s[n];lines.append(f'- `{r["id"]}` (`{n}`): “{d["description"]}” — {d["url"]}')
lines+=['','## Selected file-list evidence','']
for n,d in fl.items():
 paths=d.get('paths','').splitlines()
 selected=[]
 if n=='cinnamon-common':selected=[p for p in paths if p.endswith('.py')][:3]
 elif n=='hplip-data':selected=[p for p in paths if p.endswith('.py')][:3]
 elif n=='evolution-data-server-common':selected=[p for p in paths if p.endswith('.service')][:3]
 elif n in ['gcc-13-base','gcc-14-base','at-spi2-common']:selected=paths
 else:selected=[p for p in paths if not any(x in p for x in ['/doc/','/locale/','/icons/','/help/'])][:3] or paths[:3]
 lines.append(f'- `{n}` — {d["url"]}: '+ '; '.join('`'+p+'`' for p in selected))
lines+=['','## Verification','',f'635 unique assigned input ids equal 635 output ids; decisions are restricted to the five permitted words. Every what_it_does field is at most 15 words and every reason field at most 30 words. Counts: {dict(collections.Counter(r["decision"] for r in out.values()))}.']
Path('D1/c1/part-mint.1.notes.md').write_text('\n'.join(lines)+'\n')
